# frozen_string_literal: true

require_relative "support/harness"

# The committed build artifacts `pulpmesh/templates.rb` and `pulpmesh/assets.rb`
# are generated by `rake generate`. Regenerating them needs Erubi, which cannot
# be compiled — spinel resolves `require` at parse time, so even a guarded
# `require "erubi"` fails the build. The staleness diff therefore lives in
# `rake check`; what is checked here is what a compiled binary can check: that
# the artifacts it was built from match the sources on disk.
PROJECT = [
  File.expand_path("..", __dir__),
  __dir__
].find { |candidate| File.exist?(File.join(candidate, "spin.toml")) }

# Compared as bytes because smol.css carries an em-dash, and CRuby reads the
# file in the default external encoding, which need not be UTF-8.
Harness.check("smol.css compiled in verbatim",
              Pulpmesh::Assets::SMOL.bytes == File.read(File.join(PROJECT, "assets", "smol.css")).bytes, true)
Harness.check("syntax.css compiled in verbatim",
              Pulpmesh::Assets::SYNTAX.bytes == File.read(File.join(PROJECT, "assets", "syntax.css")).bytes, true)

# Every template has a render method, and each produces the document it should.
Harness.build("generated", Harness::FIXTURE) do |_site, out|
  Harness.check("post page is a document",
                File.read(File.join(out, "with-code.html")).start_with?("<!doctype html>"), true)
  Harness.check("index is a document",
                File.read(File.join(out, "index.html")).start_with?("<!doctype html>"), true)
  Harness.check("404 is a document",
                File.read(File.join(out, "404.html")).start_with?("<!doctype html>"), true)
  Harness.check("feed is xml",
                File.read(File.join(out, "rss.xml")).start_with?("<?xml version=\"1.0\""), true)
end
